<script setup lang="ts">
import { computed } from 'vue'
const props = defineProps<{ trace: any }>()
const calls = computed<any[]>(() => props.trace?.model_calls || [])
const tokens = computed(() => calls.value.every(c => typeof c.usage?.total_tokens === 'number') ? calls.value.reduce((n, c) => n + c.usage.total_tokens, 0) : null)
const cost = computed(() => calls.value.every(c => typeof c.cost === 'number') ? calls.value.reduce((n, c) => n + c.cost, 0) : null)
const labels: Record<string, string> = { runtime_dispatch: '运行时交接', agent_decision: '单行动决策', goal_update: '目标判断', action_rejected: '行动拒绝', observation_applied: '观察持久化', progress_checked: '进展检查', draft_readiness: '作答准入', candidate_created: '候选（未发布）', candidate_reused: '原稿异议复审（未发布）', loop_protocol_feedback: '持久协议反馈', answer_release: '原子发布凭据', loop_stopped: '安全结束', policy_coverage: '必要政策覆盖', evidence_bundle: '本轮证据', review_protocol_repair: '审核格式修复', review_incomplete: '审核未完成', budget_admission: '纠错预算检查', plan: '计划', replan: '重规划', tool_start: '开始工具', tool_result: '工具结果', evidence: '证据', context: '最终上下文', review_result: '独立审核', correction_start: '开始纠错', correction_evidence: '补查证据', answer_repair: '修复前后', clarification: '澄清', done: '最终结果', error: '错误', submission: '用户提交', retrieval_vector: '向量召回', retrieval_bm25: '关键词召回', retrieval_fusion: '融合排名', rerank: '重排' }
</script>
<template><div v-if="trace" class="trace-detail"><p v-if="trace.error">错误：{{ JSON.stringify(trace.error) }}</p><dl class="summary-grid"><dt>追踪</dt><dd>{{ trace.id }}</dd><dt>状态 / 延迟</dt><dd>{{ trace.status }} / {{ trace.elapsed_ms == null ? '未知' : Math.round(trace.elapsed_ms) + 'ms' }}</dd><dt>配置 / 索引</dt><dd>{{ trace.config_id }}<br>{{ trace.index_id }}</dd><dt>模型调用 / 已报告用量</dt><dd>{{ calls.length }} / {{ tokens ?? '不完整或未知' }}</dd><dt>费用</dt><dd>{{ cost ?? '未知（未核实计费价格）' }}</dd></dl><p>在线审核仅表示执行状态；引用可解析不等于支持结论。</p><details><summary>冻结配置与版本</summary><pre>{{ JSON.stringify(trace.snapshot, null, 2) }}</pre></details><h3>执行时间线</h3><details v-for="entry in trace.events || []" :key="entry.sequence"><summary>{{ labels[entry.kind] || entry.kind }} · {{ entry.sequence }} · {{ entry.created_at }}</summary><pre>{{ JSON.stringify(entry.payload, null, 2) }}</pre></details><details><summary>模型调用、供应商用量与错误</summary><pre>{{ JSON.stringify(calls, null, 2) }}</pre></details></div></template>
